import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"4. 已执行测试基线","description":"","frontmatter":{},"headers":[],"relativePath":"zh/publications/implementation-case-i1.0/part-02.md","filePath":"zh/publications/implementation-case-i1.0/part-02.md","lastUpdated":1786439037000}'),l={name:"zh/publications/implementation-case-i1.0/part-02.md"};function n(r,t,s,o,h,p){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="_4-已执行测试基线" tabindex="-1">4. 已执行测试基线 <a class="header-anchor" href="#_4-已执行测试基线" aria-label="Permalink to &quot;4. 已执行测试基线&quot;">​</a></h1><p>正式产品命令为 <code>npm run test:tmpa:s1.0</code>。它针对固定 Bundle 执行 CodeFlowMu 产品 Reader，并产生：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Core: S1.0</span></span>
<span class="line"><span>Implementation: CodeFlowMu V1.8.0</span></span>
<span class="line"><span>Product Reader called: true</span></span>
<span class="line"><span>Reference Reader called: false</span></span>
<span class="line"><span>PASS: 14</span></span>
<span class="line"><span>PARTIAL: 0</span></span>
<span class="line"><span>NOT RUN: 0</span></span>
<span class="line"><span>FAIL: 0</span></span>
<span class="line"><span>Aggregate: PASS</span></span></code></pre></div><p>S1.0 Reference Reader 单独报告 14/14 PASS。该结果验证作者维护的参考路径，不计为 CodeFlowMu 产品结果。</p><h1 id="_5-c01–c14-产品结果" tabindex="-1">5. C01–C14 产品结果 <a class="header-anchor" href="#_5-c01–c14-产品结果" aria-label="Permalink to &quot;5. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>准则</th><th>受测行为</th><th style="text-align:right;">强制断言数</th><th style="text-align:right;">结果</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证与无效形状拒绝</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C02</td><td>主载体与单写者不可变性</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C03</td><td>带来源 Provenance 的重复身份处理</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C04</td><td>单流连续性与异步推进</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C05</td><td>角色权限判断</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C06</td><td>生命周期合法性与状态保留</td><td style="text-align:right;">9</td><td style="text-align:right;">PASS</td></tr><tr><td>C07</td><td>职责分离与人工批准授权</td><td style="text-align:right;">10</td><td style="text-align:right;">PASS</td></tr><tr><td>C08</td><td>完整性篡改检测</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C09</td><td>缺失引用处理</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C10</td><td>禁止循环检测</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C11</td><td>聚合与重建确定性</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C12</td><td>冲突保留与显式解决</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C13</td><td>恢复行为</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr></tbody></table><p>出版审查重新计算了 71 项断言。全部 Manifest Digest、Actual-result Digest、输入 Bundle Digest 与聚合 conformance-result Digest 均与证据包记录一致。</p><h1 id="_6-s0-6-到-s1-0-工程增量" tabindex="-1">6. S0.6 到 S1.0 工程增量 <a class="header-anchor" href="#_6-s0-6-到-s1-0-工程增量" aria-label="Permalink to &quot;6. S0.6 到 S1.0 工程增量&quot;">​</a></h1><h2 id="_6-1-稳定机器身份" tabindex="-1">6.1 稳定机器身份 <a class="header-anchor" href="#_6-1-稳定机器身份" aria-label="Permalink to &quot;6.1 稳定机器身份&quot;">​</a></h2><p>S1.0 以稳定的 Schema ID、Profile Identity、Canonicalization Identity 与可执行语料路径，正式发布已经审查的 S0.6 行为。CodeFlowMu V1.8.0 把 Validator 与 Reader 绑定到这些身份，不把旧 Core 结果冒充为 S1.0 证据。</p><h2 id="_6-2-产品级投影" tabindex="-1">6.2 产品级投影 <a class="header-anchor" href="#_6-2-产品级投影" aria-label="Permalink to &quot;6.2 产品级投影&quot;">​</a></h2><p>产品 Runner 导入精确 S1.0 Bundle，通过 CodeFlowMu Protocol Surface 验证 Lifecycle Profile，创建 CodeFlowMu <code>GovernanceReader</code>，并让 FCoP 派生的来源候选通过产品路径。Reference Reader Module 为可追踪性保留在 Bundle 中，但不被产品 Runner Import 或调用。</p><h2 id="_6-3-不削弱准则的回归对齐" tabindex="-1">6.3 不削弱准则的回归对齐 <a class="header-anchor" href="#_6-3-不削弱准则的回归对齐" aria-label="Permalink to &quot;6.3 不削弱准则的回归对齐&quot;">​</a></h2><p>保留的修复前 Runtime 运行记录为 1,520 passed、2 failed、1 skipped。失败来自仍预期 V1.7 文字的过期测试，以及“QA 执行完成”与“业务裁决失败”之间区分的过期预期。测试被调整到已经实现的契约；没有削弱任何 S1.0 Schema、Fixture、强制断言、Reader 行为或通过条件。</p><p>后续一次隔离的 Wake Endpoint 失败在五次即时重复中全部通过。一次 Full Run 还停滞于 <code>TaskDispatcher.test.ts</code>；精确子进程被终止，随后有界审计报告 29 passed / 0 failed。这些记录都保留在证据包中，没有被删除。</p><h1 id="_7-回归与复现器结果" tabindex="-1">7. 回归与复现器结果 <a class="header-anchor" href="#_7-回归与复现器结果" aria-label="Permalink to &quot;7. 回归与复现器结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>表面</th><th style="text-align:right;">最终结果</th><th>解释</th></tr></thead><tbody><tr><td>CodeFlowMu TMPA Runtime Suite</td><td style="text-align:right;">24 passed / 0 failed</td><td>产品 Reader 单元与集成表面</td></tr><tr><td>CodeFlowMu Runtime Full Suite</td><td style="text-align:right;">1,522 passed / 0 failed / 1 skipped</td><td>最终完整运行</td></tr><tr><td>Runtime 分批覆盖</td><td style="text-align:right;">207/207 Files；1,522 passed / 0 failed / 1 skipped</td><td>精确文件覆盖确认</td></tr><tr><td>CodeFlowMu Shell 分批覆盖</td><td style="text-align:right;">791 passed / 0 failed</td><td>精确八批执行</td></tr><tr><td>Protocol Validation 与 Typecheck</td><td style="text-align:right;">Exit 0</td><td>Schema 与 Validator 表面</td></tr><tr><td>FCoP 锁定参考实现</td><td style="text-align:right;">1,210 passed / 2 skipped</td><td>依赖回归；不替代产品 Reader</td></tr><tr><td>精简干净环境复现器</td><td style="text-align:right;">14/14 PASS</td><td><code>npm ci</code> 加精确 S1.0 产品 Runner</td></tr></tbody></table><p>复现器最初排除了整个 Protocol Schemas 目录，因此也误删所需 S1.0 Schema。这个缩减范围失败被保留。修正后的复现器只排除无关旧材料，保留 <code>schemas/tmpa</code>，从 Lock File 安装，并成功执行相同产品 Runner。</p><h1 id="_8-保留的-wp-13-证据门禁案例" tabindex="-1">8. 保留的 WP-13 证据门禁案例 <a class="header-anchor" href="#_8-保留的-wp-13-证据门禁案例" aria-label="Permalink to &quot;8. 保留的 WP-13 证据门禁案例&quot;">​</a></h1><p>WP-13 作为多 Agent 事实核查的现场案例保留，其中包含 Executor/Reviewer 分离、证据准入、审计记录与显式生命周期边界。证据包支持的有限结论是：在捕获的任务状态中，开发完成且角色分离 QA 通过。它同时记录后续任务快照仍是 <code>review</code> 与 <code>pending</code>，计划日期提前但没有找到单独改期批准文件，并且 Runtime Binding 与签名校验和位于证据边界之外。</p><p>WP-13 说明 TMPA 为什么区分执行证据、复核证据、授权、生命周期状态与出版声明。它不是 S1.0 C01–C14 产品 Fixture，不证明理论，不独立验证 CodeFlowMu，也不证明多 Agent 系统不会产生幻觉。</p>`,21)])])}const u=e(l,[["render",n]]);export{g as __pageData,u as default};
